-- 90_VERIFY.sql — DMF0014 적용 확인 [20260827]
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('PKG_DMF0014');
SELECT COUNT(*) AS INVALID_CNT FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND STATUS='INVALID' AND OBJECT_NAME IN ('PKG_DMF0014');
SELECT 'SCM_ADM_PROGRAM' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_PROGRAM WHERE PROGRAM_ID LIKE 'DMF0014%';  -- 기대 1
SELECT 'SCM_ADM_MNU_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID LIKE 'DMF0014%';  -- 기대 1
SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID LIKE 'DMF0014%';  -- 기대 6
SELECT 'SCM_ADM_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0014%';  -- 기대 12
SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0014%';  -- 기대 60
SELECT 'SCM_ADM_API_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0014%';  -- 기대 12
SELECT 'SCM_MST_SHEET_COLUMNS/FCST Upload' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0014' AND SHEET_NAME='FCST Upload';  -- 기대 15
SELECT COUNT(*) AS GTT_CNT FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y' AND TABLE_NAME IN ('GT_DPCFRT_EDI_ALL', 'GT_DPCFRT_EDI_CUST_FCST', 'GT_DPCFRT_QTY_SUM', 'GT_DPCFSM_CALENDAR', 'GT_DPCFSM_CUST_ITEM_MAP_DTL', 'GT_DPCFSM_MIN_MAX', 'GT_DPCFSM_PSI', 'GT_DPCFSM_PSI_GROUP_COUNT', 'GT_DPCFSM_RESULTS', 'GT_DPCFSM_SITE_CUST_MAP', 'GT_DPCFSM_T2', 'GT_DPCFSM_T3', 'GT_DPCF_CALENDAR_DM_PLN_CUSTOM', 'GT_DPCF_CALENDAR_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_CUST_FCST_DIVISION', 'GT_DPCF_DM_CUST_ITEM_MAPPING_D', 'GT_DPCF_DM_CUST_ITEM_MAPPING_DTL_N', 'GT_DPCF_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_DM_PLN_CUSTOMER_PSI_2', 'GT_DPCF_MIN_MAX_PSI', 'GT_DPCF_MIN_MAX_PSI_2', 'GT_DPCF_PSI_GROUP_COUNT', 'GT_DPCF_PSI_GROUP_COUNT_2', 'GT_DPCF_RESULTS', 'GT_DPCF_RESULTS_2', 'GT_DPCF_T2_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_T3_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_TEMP2_DM_PLN_CUSTOMER', 'GT_DPCF_TEMP3_DM_PLN_CUSTOMER', 'GT_DPCF_TMP_SITE_CUSTOMER_MAP', 'GT_DPCF_TMP_SITE_CUSTOMER_MAP_2', 'GT_SCFU_RESULTS');  -- 기대 32

-- ── V11~V13 조용한-실패 게이트 (hook #148 cloud-deploy-silent-failure-gates, 2026-08-28 — §4.7-B V11 미구현 재발 정정) ──
-- V11 메뉴 행 실존 + UNIT_TP_CD='D'/USE_YN='Y' (기대 1행) — 부재 시 SCM_ADM_USER_MNU_EDIT_AUTH_V INNER JOIN 으로 오류 없이 0행
SELECT 'V11-MNU' G, MNU_ID, UNIT_TP_CD, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID='DMF0014';
-- V11-B 테스트 계정 권한 뷰 반환 행 (기대 ≥1, 조회 Division 포함) — <TEST_USER> 를 실제 로그인 ID 로
SELECT 'V11-AUTH' G, UNIT_ID, EDIT_YN FROM SCM_MGR.SCM_ADM_USER_MNU_EDIT_AUTH_V WHERE USER_ID='<TEST_USER>' AND MNU_ID='DMF0014' ORDER BY 2;
-- V12 앱 계정 EXECUTE + private synonym (기대: 객체별 SCMP_APP 각 1행 — 없으면 40_GRANT_SYNONYM.sql) — 부재 시 화면 "SQL ERROR"(PLS-00201)
SELECT 'V12-GRANT' G, TABLE_NAME, GRANTEE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND PRIVILEGE='EXECUTE' AND GRANTEE='SCMP_APP' AND TABLE_NAME IN ('PKG_DMF0014','FN_SCM_GET_WHERE_SQL','PR_DM_PLN_CUST_FCST_TO_MKT_FCST','PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40','PR_DM_SYS_LOG_BATCH','PR_SCM_SYS_LOG_BATCH','PR_GET_DAY_RANGE') ORDER BY 2;
SELECT 'V12-SYN' G, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER='SCMP_APP' AND TABLE_OWNER='SCM_MGR' AND SYNONYM_NAME IN ('PKG_DMF0014','FN_SCM_GET_WHERE_SQL','PR_DM_PLN_CUST_FCST_TO_MKT_FCST','PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40','PR_DM_SYS_LOG_BATCH','PR_SCM_SYS_LOG_BATCH','PR_GET_DAY_RANGE') ORDER BY 2;
-- V13 PKG 본문이 V_PROGRAM_ID 로 읽는 종속 PROGRAM_ID 전부의 시트 메타 (기대: 각 PROGRAM_ID 행 > 0 — 사내 값은 22/22A 파일 주석)
SELECT 'V13-META' G, PROGRAM_ID, 'COLUMNS' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID IN ('DMF0014') GROUP BY PROGRAM_ID
UNION ALL SELECT 'V13-META', PROGRAM_ID, 'MEASURE', COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID IN ('DMF0014') GROUP BY PROGRAM_ID ORDER BY 2,3;
